const totais = { total_processados: items.length, novos: 0, atualizados: 0, ignorados: 0 };
for (const item of items) {
  const status = String(item.json.status_sync ?? '');
  if (status === 'novo_sincronizado') totais.novos += 1;
  else if (status === 'atualizado_sincronizado') totais.atualizados += 1;
  else totais.ignorados += 1;
}
return [{ json: { ...totais, message: `Sincronização de candidatos concluída. ${totais.total_processados} registro(s) processado(s): ${totais.novos} novo(s), ${totais.atualizados} atualizado(s) e ${totais.ignorados} sem alteração.` } }];
